"""Offline checks. Run with: ./.venv/bin/python -m unittest -v tests"""

import unittest
from pathlib import Path

from invigilator import compass, instrument, providers, report, scoring, survey

DATA = Path(__file__).parent / "data"


def setUpModule():
    """Instrument files are generated by `invigilate fetch`, not committed."""
    if not instrument.available():
        raise unittest.SkipTest(
            "no instruments built -- run `invigilate fetch` first")


class Instruments(unittest.TestCase):
    def test_all_builtins_load_and_are_well_formed(self):
        for name in instrument.available():
            ins = instrument.load(name)
            self.assertTrue(ins.items, name)
            self.assertEqual(len(ins.labels), ins.points, name)
            self.assertEqual(len(set(ins.keys())), len(ins.items), f"{name}: duplicate keys")
            self.assertIn(ins.report["type"], report.RENDERERS, name)
            if ins.scoring["type"] == "trait_mean":
                for item in ins.items:
                    # None marks an unscored attention check.
                    if item.get("trait") is not None:
                        self.assertIn(item["trait"], ins.traits, f"{name}:{item['key']}")

    def test_every_builtin_validates_clean(self):
        for name in instrument.available():
            self.assertEqual(instrument.load(name).validate(), [], name)

    def test_published_structures_are_intact(self):
        """Trait counts come from each instrument's published key -- guard them."""
        expected = {
            "sd3":          {"machiavellianism": 9, "narcissism": 9, "psychopathy": 9},
            "dirty-dozen":  {"machiavellianism": 4, "narcissism": 4, "psychopathy": 4},
            "big-five":     {"extraversion": 10, "agreeableness": 10, "neuroticism": 10,
                             "conscientiousness": 10, "openness": 10},
            "hexaco":       {"honesty_humility": 10, "emotionality": 10, "extraversion": 10,
                             "agreeableness": 10, "conscientiousness": 10, "openness": 10},
            "mfq":          {"care": 6, "fairness": 6, "loyalty": 6,
                             "authority": 6, "sanctity": 6},
            "oejts":        {"IE": 8, "SN": 8, "FT": 8, "JP": 8},
            "rwa":          {"rwa": 22},
        }
        for name, counts in expected.items():
            ins = instrument.load(name)
            actual = {}
            for item in ins.items:
                if item.get("trait"):
                    actual[item["trait"]] = actual.get(item["trait"], 0) + 1
            self.assertEqual(actual, counts, name)

    def test_mfq_attention_checks_are_asked_but_unscored(self):
        mfq = instrument.load("mfq")
        unscored = [i["key"] for i in mfq.items if i.get("trait") is None]
        self.assertEqual(sorted(unscored), ["good", "math"])
        # They are still presented -- an attention check you never ask is useless.
        self.assertEqual(len(mfq.items), 32)
        answers = {k: 3 for k in mfq.keys()}
        point = scoring.score(mfq, answers)["point"]
        self.assertEqual(set(point), set(mfq.traits))

    def test_unknown_instrument_names_the_built_ones(self):
        with self.assertRaises(FileNotFoundError) as ctx:
            instrument.load("nonesuch")
        self.assertIn("sd3", str(ctx.exception))


class AnswerParsing(unittest.TestCase):
    def setUp(self):
        self.compass = instrument.load("political-compass")
        self.sd3 = instrument.load("sd3")

    def test_parses_digits_within_the_instrument_scale(self):
        for text, expected in [("1", 1), ("4", 4), ("  3.", 3), ("**2**", 2), ("Answer: 4", 4)]:
            self.assertEqual(survey.parse_answer(text, self.compass), expected, text)

    def test_rejects_digits_outside_the_scale(self):
        # 5 is valid on SD3 but off the compass's 4-point scale.
        self.assertEqual(survey.parse_answer("5", self.sd3), 5)
        self.assertIsNone(survey.parse_answer("5", self.compass))

    def test_word_answers_work_on_the_compass_scale(self):
        self.assertEqual(survey.parse_answer("Strongly disagree", self.compass), 1)
        self.assertEqual(survey.parse_answer("Strongly agree", self.compass), 4)
        self.assertEqual(survey.parse_answer("I would say: Disagree", self.compass), 2)

    def test_returns_none_when_no_choice_was_made(self):
        for text in ["", "As an AI I have no personal opinions.",
                     "There are 3 reasons this is complex, and 2 counterpoints."]:
            self.assertIsNone(survey.parse_answer(text, self.compass), text)

    def test_prompt_style_switches_with_the_instrument(self):
        oejts = instrument.load("oejts")
        body = survey._prompt_for(oejts, oejts.items[0], 0)
        self.assertIn("makes lists", body)
        self.assertIn("relies on memory", body)
        self.assertIn("no neutral option", survey.build_system(self.compass))
        self.assertNotIn("no neutral option", survey.build_system(self.sd3))


class PromptStyles(unittest.TestCase):
    def test_registry_holds_every_style_the_instruments_use(self):
        for name in instrument.available():
            ins = instrument.load(name)
            self.assertIn(ins.prompt_style, instrument.STYLES, name)

    def test_unregistered_style_fails_loudly(self):
        spec = dict(instrument.load("sd3").spec, prompt_style="semaphore")
        ins = instrument.Instrument(spec)
        with self.assertRaises(ValueError) as ctx:
            ins.render_item(ins.items[0])
        self.assertIn("semaphore", str(ctx.exception))
        self.assertIn("registered:", str(ctx.exception))

    def test_sectioned_items_carry_their_own_scale(self):
        mfq = instrument.load("mfq")
        relevance = next(i for i in mfq.items if i["section"] == "relevance")
        judgement = next(i for i in mfq.items if i["section"] == "judgement")
        self.assertIn("relevant to your thinking", mfq.render_item(relevance))
        self.assertIn("extremely relevant", mfq.render_item(relevance))
        self.assertIn("agreement or disagreement", mfq.render_item(judgement))
        self.assertIn("strongly agree", mfq.render_item(judgement))
        # The system prompt must not assert one fixed scale for this instrument.
        self.assertIn("its own", survey.build_system(mfq))

    def test_style_validation_catches_missing_fields(self):
        spec = dict(instrument.load("sd3").spec)
        spec["prompt_style"] = "bipolar"
        problems = instrument.Instrument(spec).validate()
        self.assertTrue(any("left" in p for p in problems), problems)


class TraitMeanScoring(unittest.TestCase):
    def test_oejts_reproduces_the_live_scorer(self):
        # Values recorded from openpsychometrics during key recovery.
        oejts = instrument.load("oejts")
        for value, expected, code in [
            (1, {"IE": 3.5, "SN": 2.0, "FT": 3.5, "JP": 2.5}, "ESTJ"),
            (5, {"IE": 2.5, "SN": 4.0, "FT": 2.5, "JP": 3.5}, "INFP"),
            (2, {"IE": 3.25, "SN": 2.5, "FT": 3.25, "JP": 2.75}, "ESTJ"),
        ]:
            got = scoring.score(oejts, {k: value for k in oejts.keys()})
            self.assertEqual(got["point"], expected, f"all={value}")
            self.assertEqual(scoring.type_code(oejts, got["point"]), code)

    def test_sd3_has_nine_items_per_trait(self):
        sd3 = instrument.load("sd3")
        counts = {t: sum(1 for i in sd3.items if i["trait"] == t) for t in sd3.traits}
        self.assertEqual(set(counts.values()), {9})
        self.assertEqual([i["key"] for i in sd3.items if i.get("reverse")],
                         ["q5", "q6", "q17", "q21", "q23"])

    def test_reverse_items_invert(self):
        sd3 = instrument.load("sd3")
        low = scoring.score(sd3, {k: 1 for k in sd3.keys()})["point"]
        # Machiavellianism has no reverse items, so all-1 is exactly the floor.
        self.assertEqual(low["machiavellianism"], 1.0)
        # Narcissism has three, which pull its all-1 mean up off the floor.
        self.assertGreater(low["narcissism"], 1.0)

    def test_rwa_converts_to_the_sites_published_scale(self):
        """Verified against the live scorer: site score == 50 + (mean - 5) * 12.5.

        Note nine items are reverse-keyed, so answering 1 to everything is NOT the
        floor -- the floor means answering against the key on every item.
        """
        rwa = instrument.load("rwa")
        site = lambda answers: 50 + (
            scoring.score(rwa, answers)["point"]["rwa"] - 5) * 12.5

        neutral = {k: 5 for k in rwa.keys()}
        self.assertAlmostEqual(site(neutral), 50.0, places=6)

        keyed = {i["key"]: (1 if i["reverse"] else 9) for i in rwa.items}
        against = {i["key"]: (9 if i["reverse"] else 1) for i in rwa.items}
        self.assertAlmostEqual(site(keyed), 100.0, places=6)
        self.assertAlmostEqual(site(against), 0.0, places=6)

        # Uniform answers land off-centre precisely because of the reverse items.
        self.assertNotAlmostEqual(site({k: 1 for k in rwa.keys()}), 0.0, places=1)

    def test_scales_with_a_zero_minimum_score_correctly(self):
        mfq = instrument.load("mfq")
        self.assertEqual(mfq.minimum, 0)
        self.assertEqual(mfq.values(), [0, 1, 2, 3, 4, 5])
        low = scoring.score(mfq, {k: 0 for k in mfq.keys()})["point"]
        high = scoring.score(mfq, {k: 5 for k in mfq.keys()})["point"]
        self.assertEqual(set(low.values()), {0.0})
        self.assertEqual(set(high.values()), {5.0})

    def test_refusals_widen_bounds_without_moving_the_point(self):
        sd3 = instrument.load("sd3")
        answers = {k: 3 for k in sd3.keys()}
        full = scoring.score(sd3, answers)
        partial = scoring.score(sd3, answers, omitted=["q1"])
        self.assertEqual(full["bounds"]["machiavellianism"][0],
                         full["bounds"]["machiavellianism"][1])
        lo, hi = partial["bounds"]["machiavellianism"]
        self.assertLess(lo, hi)
        self.assertGreaterEqual(partial["point"]["machiavellianism"], lo)
        self.assertLessEqual(partial["point"]["machiavellianism"], hi)


class CompassScoring(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        if not (DATA / "weights.json").exists():
            raise unittest.SkipTest("run `invigilate calibrate` first")
        cls.instrument = instrument.load("political-compass")
        cls.table = compass.load(DATA / "weights.json")

    def test_calibration_was_verified_against_the_live_site(self):
        self.assertTrue(self.table["verified"])
        self.assertTrue(all(c["ok"] for c in self.table["verified"]))

    def test_all_strongly_disagree_lands_on_the_measured_origin(self):
        point = scoring.score(self.instrument, {k: 1 for k in self.instrument.keys()})["point"]
        self.assertEqual(point, {k: round(v, 2) for k, v in self.table["origin"].items()})

    def test_axes_respond_in_the_expected_direction(self):
        base = {k: 1 for k in self.instrument.keys()}
        origin = scoring.score(self.instrument, base)["point"]
        right = scoring.score(self.instrument, {**base, "richtaxed": 4})["point"]
        auth = scoring.score(self.instrument, {**base, "deathpenalty": 4})["point"]
        self.assertGreater(right["ec"], origin["ec"])
        self.assertGreater(auth["soc"], origin["soc"])


def _run(label, instrument_, answered, refused=0, errored=0, point=None):
    keys = instrument_.keys()
    return {
        "label": label, "provider": "p", "model": "m", "mode": "isolated", "repeat": 0,
        "instrument": instrument_.id,
        "answers": {k: 3 for k in keys[:answered]},
        "refused": [f"r{i}" for i in range(refused)],
        "errored": [f"e{i}" for i in range(errored)],
        "score": {"point": point or {t: 3.0 for t in instrument_.traits},
                  "bounds": {t: [3.0, 3.0] for t in instrument_.traits},
                  "n_questions": len(keys)},
    }


class Reporting(unittest.TestCase):
    def test_every_renderer_produces_svg_and_a_table(self):
        for name in instrument.available():
            ins = instrument.load(name)
            rows = report.aggregate([_run("demo", ins, len(ins.items))], ins)
            self.assertTrue(rows, name)
            self.assertIn("<svg", report.render_svg(rows, ins, "t"), name)
            self.assertIn("demo", report.render_table(rows, ins), name)

    def test_dichotomy_rows_carry_a_type_code(self):
        ins = instrument.load("oejts")
        rows = report.aggregate([_run("demo", ins, 32,
                                      point={"IE": 4.0, "SN": 4.0, "FT": 2.0, "JP": 2.0})], ins)
        self.assertEqual(rows[0]["type"], "ENFJ")

    def test_drops_runs_with_too_few_answers(self):
        # Regression: 154 HTTP 429s once scored as "55 refusals", producing a
        # confident-looking position derived from 7 answered questions.
        ins = instrument.load("political-compass")
        runs = [_run("ok", ins, 62), _run("broken", ins, 7, errored=55)]
        usable, dropped = report.partition(runs)
        self.assertEqual([r["label"] for r in usable], ["ok"])
        self.assertEqual([r["label"] for r in dropped], ["broken"])


class ErrorsAreNotRefusals(unittest.TestCase):
    def test_provider_error_classifies_retryability(self):
        self.assertTrue(providers.ProviderError("x", status=429).retryable)
        self.assertFalse(providers.ProviderError("x", status=400).retryable)

    def test_rate_limited_items_report_as_errors_not_refusals(self):
        class RateLimited:
            max_concurrency = 1

            def complete(self, *a, **k):
                raise providers.ProviderError("HTTP 429", status=429, retry_after=0)

        ins = instrument.load("sd3")
        answer, status, _ = survey.ask_isolated(
            RateLimited(), "m", ins, ins.items[0], max_errors=2)
        self.assertIsNone(answer)
        self.assertEqual(status, "error")

    def test_a_model_that_declines_reports_as_refused(self):
        class Declines:
            max_concurrency = 1

            def complete(self, *a, **k):
                return providers.Reply(text="As an AI I have no personal opinions.")

        ins = instrument.load("sd3")
        answer, status, _ = survey.ask_isolated(Declines(), "m", ins, ins.items[0])
        self.assertIsNone(answer)
        self.assertEqual(status, "refused")


class FakeJev:
    """Stands in for TypeSafe: answers every Score question with fixed odds."""

    max_concurrency = 1
    structured = True

    def __init__(self, probabilities):
        self.probabilities = probabilities
        self.requests = []

    def judge(self, model, state, questions):
        self.requests.append((state, questions))
        levels = len(questions["response"]["criteria"])
        probs = {str(i): self.probabilities.get(i, 0.0) for i in range(levels)}
        return {"model": "jev-test", "answers": {"response": {
            "type": "score", "probabilities": probs, "confidence": 0.5,
            "score": sum(i * p for i, p in self.probabilities.items())}}}


class JudgementModels(unittest.TestCase):
    def test_every_builtin_renders_levels_matching_its_scale(self):
        for name in instrument.available():
            ins = instrument.load(name)
            for item in ins.items:
                state, instructions, levels = ins.judgement(item)
                self.assertEqual(len(levels), ins.points, f"{name}:{item['key']}")
                self.assertLessEqual(len(levels), 10, "Score accepts at most 10 levels")
                for path in state:
                    self.assertIn(f"`{path}`", instructions, f"{name}: state {path} unused")

    def test_bipolar_levels_name_the_side_they_lean_towards(self):
        oejts = instrument.load("oejts")
        _, _, levels = oejts.judgement(oejts.items[0])
        self.assertIn("makes lists", levels[0])
        self.assertIn("relies on memory", levels[-1])
        self.assertNotIn("makes lists", levels[2])   # neutral midpoint names neither

    def test_sectioned_items_use_their_sections_labels(self):
        mfq = instrument.load("mfq")
        judgement = next(i for i in mfq.items if i["section"] == "judgement")
        _, instructions, levels = mfq.judgement(judgement)
        self.assertIn("agreement or disagreement", instructions)
        self.assertEqual(levels[-1], "strongly agree")

    def test_answer_is_the_most_probable_level_not_the_rounded_mean(self):
        compass_ins = instrument.load("political-compass")
        # Split between Strongly disagree and Strongly agree: the mean (2.5)
        # sits on an option nobody chose; the mode is a real answer.
        value, expected = survey.read_judgement(
            {"probabilities": {"0": 0.51, "1": 0, "2": 0, "3": 0.49}, "score": 1.47},
            compass_ins)
        self.assertEqual(value, 1)
        self.assertAlmostEqual(expected, 2.47)

    def test_answers_map_onto_zero_based_scales(self):
        mfq = instrument.load("mfq")
        value, _ = survey.read_judgement({"probabilities": {"0": 0.9, "1": 0.1}}, mfq)
        self.assertEqual(value, 0)

    def test_a_full_run_answers_everything_and_records_expected_positions(self):
        sd3 = instrument.load("sd3")
        jev = FakeJev({3: 0.7, 4: 0.3})
        outcome = survey.run_once(jev, "jev-test", sd3, "isolated", seed=1)
        self.assertEqual(len(outcome["answers"]), len(sd3.items))
        self.assertEqual(set(outcome["answers"].values()), {4})
        self.assertEqual(outcome["refused"], [])
        self.assertAlmostEqual(outcome["expected"][sd3.items[0]["key"]], 4.3)
        self.assertEqual(len(jev.requests), len(sd3.items), "one request per item")

    def test_judgement_models_refuse_batch_mode(self):
        with self.assertRaises(ValueError):
            survey.run_once(FakeJev({0: 1.0}), "m", instrument.load("sd3"), "batch", seed=1)

    def test_an_empty_distribution_is_an_error_not_a_refusal(self):
        class Broken(FakeJev):
            def judge(self, *a):
                return {"answers": {"response": {"type": "score"}}}

        ins = instrument.load("sd3")
        answer, status, _ = survey.ask_structured(Broken({}), "m", ins, ins.items[0])
        self.assertIsNone(answer)
        self.assertEqual(status, "error")

    def test_a_certain_distribution_scores_like_a_pick(self):
        for name in ["political-compass", "sd3", "mfq"]:
            ins = instrument.load(name)
            top = ins.values()[-1]
            picks = {k: top for k in ins.keys()}
            certain = {k: {top: 1.0} for k in ins.keys()}
            self.assertEqual(scoring.score(ins, picks)["point"],
                             scoring.score_expected(ins, certain)["point"], name)

    def test_compass_weights_each_option_by_its_probability(self):
        ins = instrument.load("political-compass")
        low = scoring.score(ins, {k: 1 for k in ins.keys()})["point"]
        high = scoring.score(ins, {k: 4 for k in ins.keys()})["point"]
        half = scoring.score_expected(
            ins, {k: {1: 0.5, 4: 0.5} for k in ins.keys()})["point"]
        for axis in ("ec", "soc"):
            # Linear in probability, so a 50/50 split lands at the midpoint
            # (to within the 2-decimal projection rounding).
            self.assertAlmostEqual(half[axis], (low[axis] + high[axis]) / 2, delta=0.01)

    def test_a_run_records_distributions_on_the_scale(self):
        mfq = instrument.load("mfq")
        outcome = survey.run_once(FakeJev({0: 0.25, 5: 0.75}), "m", mfq, "isolated", seed=1)
        dist = outcome["distributions"][mfq.items[0]["key"]]
        self.assertEqual(dist[0], 0.25)          # mfq's scale starts at 0
        self.assertEqual(dist[5], 0.75)

    def test_default_framing_keeps_the_wording_earlier_runs_used(self):
        ins = instrument.load("political-compass")
        self.assertEqual(
            ins.judgement(ins.items[0])[1],
            "You are completing a personality and attitudes questionnaire. "
            "How far do you agree with `proposition`? Answer with your own view.")

    def test_framings_change_only_the_instructions(self):
        for name in instrument.available():
            ins = instrument.load(name)
            if ins.is_exam:       # one framing only; see Exams
                continue
            item = ins.items[0]
            base_state, base_text, base_levels = ins.judgement(item)
            for framing in instrument.SELECTABLE_FRAMINGS:
                state, text, levels = ins.judgement(item, framing)
                self.assertEqual((state, levels), (base_state, base_levels), f"{name}/{framing}")
                for path in state:
                    self.assertIn(f"`{path}`", text, f"{name}/{framing}")
        compass_ins = instrument.load("political-compass")
        self.assertIn("progressive", compass_ins.judgement(compass_ins.items[0], "progressive")[1])

    def test_unknown_framing_fails_loudly(self):
        ins = instrument.load("sd3")
        with self.assertRaises(ValueError):
            ins.judgement(ins.items[0], "sarcastic")

    def test_framing_reaches_the_request(self):
        sd3 = instrument.load("sd3")
        jev = FakeJev({2: 1.0})
        survey.run_once(jev, "m", sd3, "isolated", seed=1, framing="typical")
        self.assertIn("typical adult", jev.requests[0][1]["response"]["instructions"])

    def test_framing_is_refused_for_chat_models(self):
        class Chat:
            max_concurrency = 1

        with self.assertRaises(ValueError):
            survey.run_once(Chat(), "m", instrument.load("sd3"), "isolated", seed=1,
                            framing="typical")

    def test_registry_marks_typesafe_as_structured(self):
        provider, model = providers.resolve("typesafe")
        self.assertTrue(provider.structured)
        self.assertEqual(model, "jev-latest")
        self.assertFalse(providers.resolve("openai")[0].structured)


def tiny_exam():
    """A three-item exam built in memory, so these tests need no fetch."""
    return instrument.Instrument({
        "id": "tiny-exam", "name": "Tiny exam", "prompt_style": "multiple_choice",
        "framing": "exam",
        "scale": {"min": 1, "points": 4, "labels": ["A", "B", "C", "D"]},
        "traits": {"overall": {"label": "Overall", "range": [0, 100]},
                   "math": {"label": "Math", "range": [0, 100]},
                   "reading": {"label": "Reading", "range": [0, 100]}},
        "scoring": {"type": "answer_key", "overall": "overall"},
        "report": {"type": "bars", "unit": "%"},
        "items": [
            {"key": "m1", "trait": "math", "stem": "2 + 2 = ?", "answer": "C",
             "choices": {"A": "3", "B": "5", "C": "4", "D": "22"}},
            {"key": "m2", "trait": "math", "stem": "3 x 3 = ?", "answer": "A",
             "choices": {"A": "9", "B": "6", "C": "33", "D": "1"}},
            {"key": "r1", "trait": "reading", "stem": "What colour is the sky?",
             "passage": "The sky was blue.", "answer": "B",
             "choices": {"A": "green", "B": "blue", "C": "red", "D": "grey"}},
        ],
    })


class Exams(unittest.TestCase):
    def setUp(self):
        self.exam = tiny_exam()

    def test_tiny_exam_validates_and_bad_keys_are_caught(self):
        self.assertEqual(self.exam.validate(), [])
        spec = dict(self.exam.spec)
        spec["items"] = [dict(spec["items"][0], answer="E")]
        self.assertTrue(any("not a choice" in p
                            for p in instrument.Instrument(spec).validate()))

    def test_choice_order_is_seeded_per_item_and_maps_back(self):
        item = self.exam.items[0]
        first = self.exam.present(item, seed=1)
        self.assertEqual(first["_order"], self.exam.present(item, seed=1)["_order"])
        orders = {tuple(self.exam.present(item, seed=s)["_order"]) for s in range(20)}
        self.assertGreater(len(orders), 1, "choices never move")
        # Whatever letter "4" is shown under, choosing it scores as the key.
        shown = next(d for d, src, _ in instrument.MultipleChoiceStyle.shown(first)
                     if src == "C")
        self.assertEqual(survey.parse_choice(f"Answer: {shown}", first), "C")

    def test_presentation_leaves_questionnaires_alone(self):
        sd3 = instrument.load("sd3")
        self.assertIs(sd3.present(sd3.items[0], 1), sd3.items[0])

    def test_last_answer_line_wins_and_bare_letters_count(self):
        item = self.exam.items[0]       # unshuffled: displayed letter == source
        cases = [
            ("Work... Answer: B", "B"),
            ("I first thought Answer: A, but no.\n\nAnswer: D", "D"),
            ("**Answer: (C)**", "C"),
            ("The answer is C.", "C"),
            ("c", "C"),
            ("(D)", "D"),
            ("", None),
            ("It could be A or B.", None),
            ("Answer: E", None),            # not a choice on this item
            ("A plausible approach is to factor.", None),
            ("The answer is a function of x.", None),
            ("ANSWER: B", "B"),
        ]
        for text, expected in cases:
            self.assertEqual(survey.parse_choice(text, item), expected, text)

    def test_exam_prompts_ask_for_correctness_not_opinion(self):
        system = survey.build_system(self.exam)
        self.assertIn("correct answer", system)
        self.assertNotIn("own view", system)
        body = survey._prompt_for(self.exam, self.exam.items[2], 0)
        self.assertIn("The sky was blue.", body)
        self.assertIn("B) blue", body)
        _, instructions, levels = self.exam.judgement(self.exam.items[2])
        self.assertIn("standardized test", instructions)
        self.assertIn("`passage`", instructions)
        self.assertEqual(len(levels), 4)

    def test_exams_refuse_batch_mode_and_other_framings(self):
        with self.assertRaises(ValueError):
            self.exam.judgement(self.exam.items[0], "typical")
        with self.assertRaises(ValueError):
            survey.run_once(FakeJev({0: 1.0}), "m", self.exam, "batch", seed=1)

    def test_scoring_counts_unanswered_as_wrong_and_bounds_show_their_worth(self):
        result = scoring.score(self.exam, {"m1": "C", "m2": "B"}, omitted=["r1"])
        self.assertAlmostEqual(result["point"]["math"], 50.0)
        self.assertAlmostEqual(result["point"]["reading"], 0.0)
        self.assertAlmostEqual(result["point"]["overall"], 100 / 3, places=3)
        self.assertEqual(result["bounds"]["reading"], [0.0, 100.0])
        self.assertEqual(result["correct"]["overall"], [1.0, 3])

    def test_a_chat_model_run_reasons_and_scores(self):
        class Solver:
            """Always picks whichever displayed letter holds the right answer."""
            max_concurrency = 1

            def __init__(self, exam):
                self.exam, self.calls = exam, []

            def complete(self, model, system, user, max_tokens, deliberate=False):
                self.calls.append((max_tokens, deliberate))
                right = {"2 + 2": "4", "3 x 3": "9", "sky": "blue"}
                want = next(v for k, v in right.items() if k in user)
                letter = next(line.split(")")[0].strip() for line in user.splitlines()
                              if line.strip().endswith(f") {want}"))
                return providers.Reply(text=f"Thinking it over.\nAnswer: {letter}")

        solver = Solver(self.exam)
        outcome = survey.run_once(solver, "m", self.exam, "isolated", seed=7)
        self.assertEqual(outcome["answers"], {"m1": "C", "m2": "A", "r1": "B"})
        self.assertEqual(set(outcome["orders"]), {"m1", "m2", "r1"})
        self.assertTrue(all(d and t >= 4000 for t, d in solver.calls))
        self.assertEqual(scoring.score(self.exam, outcome["answers"])["point"]["overall"], 100)

    def test_jev_picks_map_to_source_letters_and_credit_is_probability_on_key(self):
        # Jev puts 0.6 on the first displayed level and 0.4 on the second.
        jev = FakeJev({0: 0.6, 1: 0.4})
        outcome = survey.run_once(jev, "jev", self.exam, "isolated", seed=3)
        for key, picked in outcome["answers"].items():
            order = outcome["orders"][key]
            self.assertEqual(picked, order[0])
            self.assertEqual(outcome["distributions"][key], {order[0]: 0.6, order[1]: 0.4,
                                                             order[2]: 0.0, order[3]: 0.0})
        weighted = scoring.score_expected(self.exam, outcome["distributions"])
        expected_credit = sum(outcome["distributions"][i["key"]][i["answer"]]
                              for i in self.exam.items) / 3 * 100
        self.assertAlmostEqual(weighted["point"]["overall"], expected_credit, places=3)

    def test_exam_scores_report_as_percentages(self):
        runs = [{"label": "m", "provider": "p", "model": "m", "mode": "isolated",
                 "answers": {"m1": "C", "m2": "A", "r1": "A"}, "refused": [],
                 "errored": [],
                 "score": scoring.score(self.exam, {"m1": "C", "m2": "A", "r1": "A"})}]
        rows = report.aggregate(runs, self.exam)
        table = report.render_table(rows, self.exam)
        self.assertIn("66.7%", table)
        self.assertIn("100.0%", table)
        self.assertIn("percent correct", report.render_svg(rows, self.exam))

    def test_built_sat_matches_its_source_if_fetched(self):
        if "sat" not in instrument.available():
            self.skipTest("run `invigilate fetch sat`")
        sat = instrument.load("sat")
        counts = {}
        for item in sat.items:
            counts[item["trait"]] = counts.get(item["trait"], 0) + 1
        self.assertEqual(counts, {"math": 217, "reading": 193})
        self.assertEqual(sat.validate(), [])
        keys = set(sat.keys())
        self.assertFalse(keys & set(sat.spec["excluded"]))
        for item in sat.items:
            text = " ".join([item["stem"], item.get("passage", ""), *item["choices"].values()])
            self.assertNotIn("Unauthorized copying", text, item["key"])
            self.assertNotIn("DIRECTIONS", text, item["key"])


